  estado: ok ? 'COMPLETADO' : 'DETENIDO',
  resultado: ok ? 'Productos existentes, con inventario suficiente y precios identicos al catalogo autorizado. Se calcula la cotizacion.' : 'Proceso detenido: ' + motivo,
  fuentes: [cat.fuente], advertencias: [], duracion_ms: 0,
  referencia_consumo: { execution_id: $execution.id, tokens_entrada: null, tokens_salida: null, costo_usd: null, nota: 'Logica determinista.' }
};
return [{ json: Object.assign({}, prev, {
  estado_flujo: ok ? 'OK' : 'DETENIDO', motivo_detencion: motivo,
  agente2: out, items_verificados: verificados,
  advertencias: prev.advertencias.concat(adv),
  trazas: prev.trazas.concat([trazaAg, trazaOrq]),
  presupuesto: Object.assign({}, prev.presupuesto, { llamadas_ia_realizadas: prev.presupuesto.llamadas_ia_realizadas }),
  _t_prep: Date.now()
}) }];

const s = $input.first().json;
const r2 = function (n) { return Math.round(n * 100) / 100; };
const lineas = s.items_verificados.map(function (i) {
  return { producto: i.producto, cantidad: i.cantidad, precio_unitario: i.precio_unitario, subtotal: r2(i.cantidad * i.precio_unitario) };
});
const subtotal = r2(lineas.reduce(function (a, l) { return a + l.subtotal; }, 0));
const cotizacion = {
  caso_id: s.caso_id, lineas: lineas, subtotal: subtotal, impuestos: 0, envio: 0, descuentos: 0,
