const s = $input.first().json;
const c = s.cotizacion;
const a3 = s.agente3;
const cat = s.catalogo;
const norm = function (x) { return String(x || '').toLowerCase().replace('producto', '').trim(); };
const r2 = function (n) { return Math.round(n * 100) / 100; };
const checks = [];
