chk('caso_id_consistente', 'El caso_id es el mismo en el Agente 1, 2 y 3', [s.agente1.caso_id, s.agente2.caso_id, a3.caso_id, c.caso_id].every(function (x) { return x === s.caso_id; }));
chk('productos_y_cantidades', 'Productos y cantidades de la cotizacion coinciden con lo extraido por el Agente 1', s.agente1.productos.every(function (p) {
  const l = c.lineas.find(function (x) { return norm(x.producto) === norm(p.nombre); });
  return l && l.cantidad === Number(p.cantidad);
}) && s.agente1.productos.length === c.lineas.length);
chk('precios_vs_catalogo', 'Cada precio unitario coincide con el catalogo autorizado', c.lineas.every(function (l) {
  const k = norm(l.producto); return cat.productos[k] && cat.productos[k].precio === l.precio_unitario;
}));
chk('inventario_suficiente', 'Ninguna cantidad supera el inventario autorizado', c.lineas.every(function (l) {
  const k = norm(l.producto); return cat.productos[k] && l.cantidad <= cat.productos[k].inventario;
}));
chk('subtotales', 'Cada subtotal = cantidad x precio unitario', c.lineas.every(function (l) { return r2(l.cantidad * l.precio_unitario) === l.subtotal; }));
chk('total', 'El total = suma de subtotales', r2(c.lineas.reduce(function (a, l) { return a + l.subtotal; }, 0)) === c.total && c.total === c.subtotal);
chk('sin_extras', 'No hay impuestos, envio ni descuentos inventados (cotizacion y propuesta)', c.impuestos === 0 && c.envio === 0 && c.descuentos === 0 && Number(a3.impuestos) === 0 && Number(a3.envio) === 0 && Number(a3.descuentos) === 0);
chk('propuesta_coincide_calculo', 'La propuesta del Agente 3 tiene el mismo total y moneda que el calculo', Number(a3.total) === c.total && a3.moneda === c.moneda);
chk('fuente_catalogo', 'La fuente del catalogo esta presente y coincide', c.fuente === cat.fuente && s.agente2.fuente === cat.fuente);
chk('politica', 'Modo SIMULADO y moneda MXN', s.modo === 'SIMULADO' && c.moneda === 'MXN');
const trazaOrq = {
