  referencia_consumo: Object.assign({execution_id:$execution.id},prev.presupuesto.registros.at(-1))
};
const trazaOrq = {
  caso_id: prev.caso_id, agente: 'ORQUESTADOR', etapa: 'revision_agente_4',
  estado: aprobado ? 'COMPLETADO' : 'DEVUELTO',
  resultado: aprobado ? 'Dictamen del Agente 4 y validaciones deterministas coinciden: APROBADO_TECNICAMENTE. Pasa a cierre con aprobacion humana pendiente.' : 'Cotizacion DEVUELTA: ' + revision.hallazgos.join('; '),
  fuentes: ['Agente 4', 'Validaciones deterministas QA'], advertencias: [], duracion_ms: 0,
  referencia_consumo: { execution_id: $execution.id, tokens_entrada: null, tokens_salida: null, costo_usd: null, nota: 'Logica determinista.' }
};
return [{ json: Object.assign({}, prev, {
  estado_flujo: aprobado ? 'OK' : 'DEVUELTO',
  motivo_detencion: aprobado ? null : revision.hallazgos.join('; '),
  agente4: out, revision_tecnica: revision,
  advertencias: prev.advertencias.concat(adv),
  trazas: prev.trazas.concat([trazaAg, trazaOrq]),
  presupuesto: Object.assign({}, prev.presupuesto, { llamadas_ia_realizadas: prev.presupuesto.llamadas_ia_realizadas }),
  _t_prep: Date.now()
}) }];

